import{_ as a,c as e,o as r,ag as o}from"./chunks/framework.DQvKz0xt.js";const f=JSON.parse('{"title":"路径跟随约束 (Follow Path Constraint) - Rive 编辑器","description":"约束 (Constraints) 路径跟随约束通过将对象约束到一条路径上，大大简化了复杂运动轨迹的创建。","frontmatter":{"title":"路径跟随约束 (Follow Path Constraint) - Rive 编辑器","description":"约束 (Constraints) 路径跟随约束通过将对象约束到一条路径上，大大简化了复杂运动轨迹的创建。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 约束, 路径跟随约束"}]]},"headers":[],"relativePath":"editor/constraints/follow-path-constraint.md","filePath":"editor/constraints/follow-path-constraint.md","lastUpdated":1774838907000}'),n={name:"editor/constraints/follow-path-constraint.md"};function i(s,t,l,h,p,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<p>约束 (Constraints)</p><h1 id="路径跟随约束-follow-path-constraint" tabindex="-1">路径跟随约束 (Follow Path Constraint) <a class="header-anchor" href="#路径跟随约束-follow-path-constraint" aria-label="Permalink to &quot;路径跟随约束 (Follow Path Constraint)&quot;">​</a></h1><p>路径跟随约束通过将对象约束到一条路径上，大大简化了复杂运动轨迹的创建。</p><h2 id="​-设置路径跟随约束" tabindex="-1"><a href="#setting-up-a-follow-path-constraint">​</a> 设置路径跟随约束 <a class="header-anchor" href="#​-设置路径跟随约束" aria-label="Permalink to &quot;[​](#setting-up-a-follow-path-constraint) 设置路径跟随约束&quot;">​</a></h2><ol><li>首先，你需要一个要约束的对象和一条用作路径的曲线。</li><li>选中对象，添加新约束并选择 <strong>Follow Path Constraint</strong>。 <img src="https://help.rive.app/images/image_0.png" alt="添加路径跟随约束"></li><li>点击 Target 按钮，选择你希望对象跟随的路径。</li></ol><h2 id="​-路径跟随属性" tabindex="-1"><a href="#follow-path-properties">​</a> 路径跟随属性 <a class="header-anchor" href="#​-路径跟随属性" aria-label="Permalink to &quot;[​](#follow-path-properties) 路径跟随属性&quot;">​</a></h2><p>与其他约束类似，路径跟随约束有多个可自定义的属性。</p><h4 id="​-强度-strength" tabindex="-1"><a href="#strength">​</a> 强度 (Strength) <a class="header-anchor" href="#​-强度-strength" aria-label="Permalink to &quot;[​](#strength) 强度 (Strength)&quot;">​</a></h4><p>控制受约束对象对路径的遵循程度。</p><h4 id="​-目标-target" tabindex="-1"><a href="#target">​</a> 目标 (Target) <a class="header-anchor" href="#​-目标-target" aria-label="Permalink to &quot;[​](#target) 目标 (Target)&quot;">​</a></h4><p>指定要跟随的路径对象。</p><h4 id="​-距离-distance" tabindex="-1"><a href="#distance">​</a> 距离 (Distance) <a class="header-anchor" href="#​-距离-distance" aria-label="Permalink to &quot;[​](#distance) 距离 (Distance)&quot;">​</a></h4><p>该属性控制对象沿路径移动的位置。百分比增加时，对象沿路径前进。<em>注意：该值可以超过 100%。</em><img src="https://help.rive.app/images/image_1.png" alt="距离属性效果"></p><h4 id="​-朝向-orient" tabindex="-1"><a href="#orient">​</a> 朝向 (Orient) <a class="header-anchor" href="#​-朝向-orient" aria-label="Permalink to &quot;[​](#orient) 朝向 (Orient)&quot;">​</a></h4><p>控制受约束对象的旋转方式。</p><ul><li><strong>开启</strong>：对象的旋转会自动跟随路径的切线方向。此时无法手动调整对象旋转。 <img src="https://help.rive.app/images/image_2.png" alt="朝向开启效果"></li><li><strong>关闭</strong>：对象旋转不受路径影响，你可以手动设置任意旋转角度。</li></ul><h4 id="​-偏移-offset" tabindex="-1"><a href="#offset">​</a> 偏移 (Offset) <a class="header-anchor" href="#​-偏移-offset" aria-label="Permalink to &quot;[​](#offset) 偏移 (Offset)&quot;">​</a></h4><p>允许对象沿路径移动，但保持其当前位置作为偏移起点。</p><p><a href="/docs/editor/constraints/translation-constraint">位移约束 (Translation Constraint)</a><a href="/docs/editor/constraints/scroll-constraint">滚动约束 (Scroll Constraints)</a></p>',19)])])}const g=a(n,[["render",i]]);export{f as __pageData,g as default};
